<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { amount } from '../catalog';
import { quantity } from '../inventory';
import { pendingAmount, type CartLine, type SalesCustomer, type SalesQuote, type SavedOrder } from '../sales';
import PaymentHistory from './PaymentHistory.vue';
import SalesReturnReceipt from './SalesReturnReceipt.vue';
import CreditApplication from './CreditApplication.vue';

const props = defineProps<{ customer: SalesCustomer | null; lines: CartLine[]; quote: SalesQuote | null; currency: string; mode: 'sale' | 'reservation'; discount: string; shipping: string; paid: string; method: string; delivery: string; notes: string; waiting: boolean; busy: boolean; uncertain: boolean; order: SavedOrder | null; canCreate: boolean; canPay: boolean; canCancel: boolean; paymentContext?:{root:string;actorId:number;canReverse:boolean;canReceive?:boolean;canAdjust?:boolean;canRefund?:boolean;canApply?:boolean;canDownload?:boolean;canReverseCredit?:boolean;canReverseReturn?:boolean;canReverseRefund?:boolean;canReverseAdjustment?:boolean} }>();
const emit = defineEmits<{ 'update:mode': ['sale' | 'reservation']; 'update:discount': [string]; 'update:shipping': [string]; 'update:paid': [string]; 'update:method': [string]; 'update:delivery': [string]; 'update:notes': [string]; selectCustomer: []; quantity: [number, number]; remove: [number]; submit: ['sale' | 'reservation']; action: [string, number?]; share: []; pdf: []; paymentsChanged:[SavedOrder] }>();
const remaining = computed(() => props.order?.pending_total || pendingAmount(props.quote?.grand_total, props.paid));
const totals = computed(() => props.order ? {...props.order,grand_total:props.order.net_total??props.order.grand_total} : props.quote);
const status = computed(() => props.order ? ({ reserved: 'Reserva activa', confirmed: 'Facturado · pendiente de entrega', fulfilled: 'Entregado', cancelled: 'Cancelado' }[props.order.status]) : 'Borrador');
const panel = ref<HTMLElement>();
let observer: ResizeObserver | undefined;
function measure() { if (!panel.value) return; const height = window.visualViewport?.height || innerHeight; const top = panel.value.getBoundingClientRect().top; panel.value.style.setProperty('--sales-summary-height', `${Math.max(260, height - Math.max(top, 110) - 16)}px`); }
onMounted(() => { observer = new ResizeObserver(measure); if (panel.value?.parentElement) observer.observe(panel.value.parentElement); window.addEventListener('resize', measure); window.addEventListener('scroll', measure, { passive: true }); window.visualViewport?.addEventListener('resize', measure); measure(); });
onUnmounted(() => { observer?.disconnect(); window.removeEventListener('resize', measure); window.removeEventListener('scroll', measure); window.visualViewport?.removeEventListener('resize', measure); });
const disabled = computed(() => props.busy || props.waiting || !props.canCreate || (!props.uncertain && (!props.quote || !props.customer || props.customer.status === 'archived' || remaining.value === null)));
</script>
<template>
    <section ref="panel" class="sales-summary sales-surface" :class="{ persisted: !!order }" aria-label="Resumen de la operación">
        <div v-if="order || mode === 'reservation'" class="sales-summary-heading"><h2>{{ order ? `Pedido #${order.id}` : 'Apartado' }}</h2><span class="badge" :class="{ inactive: !order || order.status === 'cancelled' }">{{ status }}</span></div>
        <button v-if="!order" type="button" class="sales-selected-customer" :disabled="busy || uncertain" @click="emit('selectCustomer')"><span class="customer-initials">{{ customer?.full_name.slice(0,1) || '+' }}</span><span><small>Cliente</small><strong>{{ customer?.full_name || 'Seleccionar cliente' }}</strong></span></button>
        <div v-else class="sales-selected-customer"><span class="customer-initials">{{ order.customer_snapshot.full_name.slice(0,1) }}</span><span><small>Cliente</small><strong>{{ order.customer_snapshot.full_name }}</strong></span></div>
        <p v-if="!order && customer?.status === 'archived'" class="notice">Cliente archivado. Selecciona un cliente activo para registrar una nueva venta.</p>
        <div class="sales-summary-scroll"><div class="sales-order-lines" aria-label="Artículos de la operación">
            <template v-if="!order"><article v-for="line in lines" :key="line.variant_id" class="sales-order-line"><img v-if="line.image" :src="line.image" :alt="line.name"><span v-else class="line-photo-fallback">{{ line.name.slice(0,1) }}</span><div class="line-description"><strong>{{ line.name }}</strong><small>{{ line.attributes.map(a => `${a.name}: ${a.value}`).join(' · ') || line.sku }}</small><b>{{ amount(line.price, currency) }}</b></div><div class="line-quantity"><button type="button" :disabled="busy || uncertain" :aria-label="`Restar ${line.sku}`" @click="emit('quantity', line.variant_id, -1)">−</button><span>{{ quantity(line.quantity) }}</span><button type="button" :disabled="busy || uncertain" :aria-label="`Sumar ${line.sku}`" @click="emit('quantity', line.variant_id, 1)">+</button></div><button type="button" class="icon-button" :disabled="busy || uncertain" :aria-label="`Quitar ${line.sku}`" @click="emit('remove', line.variant_id)">×</button></article></template>
            <template v-else><article v-for="line in order.items" :key="line.id" class="sales-order-line saved"><img v-if="line.image_url_snapshot" :src="line.image_url_snapshot" :alt="line.product_name_snapshot"><span v-else class="line-photo-fallback">{{ line.product_name_snapshot.slice(0,1) }}</span><div class="line-description"><strong>{{ line.product_name_snapshot }}</strong><small>{{ line.variant_snapshot?.map(a => `${a.name}: ${a.value}`).join(' · ') || line.sku_snapshot }}</small><b>{{ quantity(line.quantity) }} × {{ amount(line.unit_price, currency) }}</b></div><button v-if="canCreate && order.status === 'reserved' && !order.invoice" type="button" class="icon-button" :disabled="busy || order.items.length < 2 || order.paid_total !== '0.0000'" :aria-label="`Retirar ${line.sku_snapshot}`" @click="emit('action', 'remove', line.id)">×</button></article></template>
            <p v-if="!order && !lines.length" class="empty">Selecciona productos para empezar.</p>
        </div>
        <details v-if="!order" class="sales-adjustments"><summary>Descuento, envío y {{ mode === 'reservation' ? 'abono' : 'pago' }}</summary><fieldset class="sales-amount-fields" :disabled="busy || uncertain"><label>Descuento {{ currency }}<input :value="discount" inputmode="decimal" maxlength="20" @input="emit('update:discount', ($event.target as HTMLInputElement).value.replace(',', '.'))"></label><label>Envío {{ currency }}<input :value="shipping" inputmode="decimal" maxlength="20" @input="emit('update:shipping', ($event.target as HTMLInputElement).value.replace(',', '.'))"></label><label v-if="canPay">{{ mode === 'reservation' ? 'Abono inicial' : 'Pago recibido' }} {{ currency }}<input :value="paid" inputmode="decimal" maxlength="20" @input="emit('update:paid', ($event.target as HTMLInputElement).value.replace(',', '.'))"></label><label v-if="canPay">Método<select :value="method" aria-label="Método de pago" @change="emit('update:method', ($event.target as HTMLSelectElement).value)"><option value="cash">Efectivo</option><option value="bank_transfer">Transferencia bancaria</option><option value="card">Tarjeta</option></select></label><label class="sales-delivery">Entrega estimada<input type="date" :value="delivery" @input="emit('update:delivery', ($event.target as HTMLInputElement).value)"></label><label class="sales-delivery">Notas de la operación<textarea :value="notes" rows="2" maxlength="4000" @input="emit('update:notes', ($event.target as HTMLTextAreaElement).value)"></textarea></label></fieldset></details></div>
        <dl class="sales-totals"><div><dt>Subtotal</dt><dd>{{ amount(totals?.subtotal, currency) }}</dd></div><div><dt>Descuento</dt><dd>{{ amount(totals?.discount_total, currency) }}</dd></div><div v-if="totals && totals.tax_total !== '0.0000'"><dt>Impuestos</dt><dd>{{ amount(totals?.tax_total, currency) }}</dd></div><div><dt>Envío</dt><dd>{{ amount(totals?.shipping_total, currency) }}</dd></div><div v-if="order || mode === 'reservation'"><dt>{{ order ? 'Abonos registrados' : 'Abono inicial' }}</dt><dd>{{ amount(order?.paid_total || paid || '0', currency) }}</dd></div><div class="sales-total-emphasis"><dt>{{ mode === 'reservation' || order ? 'Total pendiente' : 'Total' }}</dt><dd>{{ amount(mode === 'reservation' || order ? remaining : totals?.grand_total, currency) }}</dd></div></dl>
        <p v-if="waiting" class="muted" role="status">Calculando importes…</p><p v-if="!customer && !order" class="muted">Selecciona un cliente para confirmar.</p><p v-if="remaining === null" class="notice error" role="alert">El abono debe ser válido y no superar el total.</p>
        <footer class="sales-summary-actions"><template v-if="!order"><button type="button" class="button primary full" :disabled="disabled" @click="emit('submit', mode)">{{ uncertain && !busy ? 'Reintentar la misma operación' : mode === 'reservation' ? 'Guardar como apartado' : 'Facturar y enviar' }}</button><button v-if="mode === 'sale' && !uncertain" type="button" class="button secondary full" :disabled="disabled" @click="emit('submit', 'reservation')">Guardar como apartado</button><p class="sales-action-note">{{ mode === 'reservation' ? 'Reserva efectiva al guardar.' : 'PDF privado · Compartir manualmente.' }}</p></template>
        <template v-else><p v-if="order.invoice" class="notice">Factura {{ order.invoice.invoice_number }} · {{ order.invoice.status === 'paid' ? 'Pagada' : 'Pendiente de cobro' }}</p><button v-if="!order.invoice && order.status !== 'cancelled' && canCreate" type="button" class="button primary full" :disabled="busy" @click="emit('action', 'invoice')">Facturar ahora</button><button v-if="order.status !== 'fulfilled' && order.status !== 'cancelled' && canCreate" type="button" class="button secondary full" :disabled="busy" @click="emit('action', 'deliver')">Registrar entrega</button><button v-if="order.pending_total !== '0.0000' && order.status !== 'cancelled' && canPay" type="button" class="button secondary full" :disabled="busy" @click="emit('action', 'payment')">Registrar abono</button><button v-if="order.invoice" type="button" class="button secondary full" :disabled="busy" @click="emit('pdf')">Descargar factura PDF</button><button type="button" class="button secondary full" :disabled="busy" @click="emit('share')">Compartir resumen</button><button v-if="!order.invoice && order.status === 'reserved' && canCancel" type="button" class="text-button" :disabled="busy || order.paid_total !== '0.0000'" @click="emit('action', 'cancel')">Cancelar canasta sin abonos</button><p v-if="order.paid_total !== '0.0000' && !order.invoice" class="sales-action-note">Los abonos se conservan. Retirar artículos o cancelar requiere resolver su devolución explícitamente.</p></template>
        <p v-if="order?.return_pending" class="notice" role="status">Devolución recibida: ajuste económico pendiente. El saldo original está pendiente de conciliación y el cobro está bloqueado.</p>
        <p v-if="order?.return_credit_total&&order.return_credit_total!=='0.0000'" class="notice">Original {{ amount(order.original_total||order.grand_total,currency) }} · Ajuste {{ amount(order.return_credit_total,currency) }} · Neto {{ amount(order.net_total,currency) }} · Saldo a favor {{ amount(order.credit_available||'0',currency) }} · Reembolso registrado {{ amount(order.refunded_total||'0',currency) }}</p>
        <PaymentHistory v-if="order&&paymentContext" :key="`${paymentContext.root}:${order.id}`" :root="paymentContext.root" :actor-id="paymentContext.actorId" :order="order" :can-reverse="paymentContext.canReverse&&!order.return_pending" :disabled="busy||uncertain" @changed="emit('paymentsChanged',$event)" />
        <SalesReturnReceipt v-if="order?.invoice&&paymentContext" :key="`return:${paymentContext.root}:${order.id}`" :root="paymentContext.root" :actor-id="paymentContext.actorId" :order="order" :can-receive="!!paymentContext.canReceive" :can-adjust="!!paymentContext.canAdjust" :can-refund="!!paymentContext.canRefund" :can-download="!!paymentContext.canDownload" :can-reverse-return="!!paymentContext.canReverseReturn" :can-reverse-refund="!!paymentContext.canReverseRefund" :can-reverse-adjustment="!!paymentContext.canReverseAdjustment" :disabled="busy||uncertain" @changed="emit('paymentsChanged',$event)" />
        <CreditApplication v-if="order?.invoice&&paymentContext" :key="`credit:${paymentContext.root}:${order.id}`" :root="paymentContext.root" :actor-id="paymentContext.actorId" :order="order" :can-apply="!!paymentContext.canApply" :can-download="!!paymentContext.canDownload" :can-reverse-credit="!!paymentContext.canReverseCredit" :disabled="busy||uncertain" @changed="emit('paymentsChanged',$event)"/>
        <p v-if="order?.credit_received_total&&order.credit_received_total!=='0.0000'" class="notice">Crédito recibido de otras operaciones: {{ amount(order.credit_received_total,currency) }}. Recibido originalmente en este pedido: {{ amount(order.gross_received||'0',currency) }}.</p>
        </footer>
    </section>
</template>
